func findMinMax(data []interface{}) (float64, float64) {
        if len(data) == 0 {
                return 0, 0
        }
        minVal, _ := toFloat(data[0])
        maxVal := minVal
        for _, v := range data[1:] {
                val, err := toFloat(v)
                if err != nil {
                        continue
                }
                if val < minVal {
                        minVal = val
                }
                if val > maxVal {
                        maxVal = val
                }
        }
        return minVal, maxVal
}

func sortedCopy(values []float64) []float64 {
        s := make([]float64, len(values))
        copy(s, values)
        sort.Float64s(s)
        return s
}
