// ExecuteTransform applies a data transformation.
// Supported modes: scale, offset, normalize, identity, clip, log.
func ExecuteTransform(config, input map[string]interface{}) (map[string]interface{}, error) {
        data, ok := input["data"].([]interface{})
        if !ok {
                return nil, fmt.Errorf("transform: missing or invalid 'data' field in input")
        }

        mode, _ := config["mode"].(string)
        if mode == "" {
                return nil, fmt.Errorf("transform: missing 'mode' in config")
        }

        result := make([]interface{}, len(data))

        switch mode {
        case "scale":
                factor, _ := config["factor"].(float64)
                for i, v := range data {
                        val, err := toFloat(v)
                        if err != nil {
                                return nil, fmt.Errorf("transform scale: element %d: %w", i, err)
                        }
                        result[i] = val * factor
                }

        case "offset":
                offset, _ := config["offset"].(float64)
                for i, v := range data {
                        val, err := toFloat(v)
                        if err != nil {
                                return nil, fmt.Errorf("transform offset: element %d: %w", i, err)
                        }
                        result[i] = val + offset
                }

        case "normalize":
                if len(data) == 0 {
                        return map[string]interface{}{"data": result}, nil
                }
                minVal, maxVal := findMinMax(data)
                for i, v := range data {
                        val, err := toFloat(v)
                        if err != nil {
                                return nil, fmt.Errorf("transform normalize: element %d: %w", i, err)
                        }
                        if maxVal == minVal {
                                result[i] = 0.5
                        } else {
                                result[i] = (val - minVal) / (maxVal - minVal)
                        }
                }

        case "identity":
                copy(result, data)

        case "clip":
                low, _ := config["low"].(float64)
                high, _ := config["high"].(float64)
                for i, v := range data {
                        val, err := toFloat(v)
                        if err != nil {
                                return nil, fmt.Errorf("transform clip: element %d: %w", i, err)
                        }
                        if val < low {
                                val = low
                        }
                        if val > high {
                                val = high
                        }
                        result[i] = val
                }
