func shouldSkipStep(config map[string]interface{}, variables map[string]float64) (bool, error) {
	cond, ok := config["skip_condition"]
	if !ok {
		return false, nil
	}
	c, ok := cond.(map[string]interface{})
	if !ok {
		return false, fmt.Errorf("skip_condition must be an object")
	}
	varName, _ := c["var"].(string)
	if varName == "" {
		return false, fmt.Errorf("skip_condition requires var")
	}
	val, exists := variables[varName]
	if !exists {
		return false, nil
	}
	op, _ := c["op"].(string)
	threshold, err := toFloat(c["threshold"])
	if err != nil {
		return false, fmt.Errorf("skip_condition invalid threshold: %w", err)
	}
	switch op {
	case "gt": return val > threshold, nil
	case "lt": return val < threshold, nil
	case "eq": return val == threshold, nil
	case "gte": return val >= threshold, nil
	case "lte": return val <= threshold, nil
	case "ne": return val != threshold, nil
	default: return false, fmt.Errorf("skip_condition unsupported operator %q", op)
	}
}

