// GetModel returns a model with its versions sorted by version number descending.
func (r *Registry) GetModel(name string) (*Model, error) {
        r.mu.RLock()
        defer r.mu.RUnlock()

        model, exists := r.models[name]
        if !exists {
                return nil, fmt.Errorf("model %q not found", name)
