        // Return a copy with versions sorted
        result := *model
        result.Versions = make([]*Version, len(model.Versions))
        copy(result.Versions, model.Versions)
        sort.Slice(result.Versions, func(i, j int) bool {
                return result.Versions[i].Number > result.Versions[j].Number
        })
        return &result, nil
}

