New:
```go
func substituteParameters(tmpl *Template, params map[string]interface{}) (*pipeline.Pipeline, map[string]interface{}, []string, error) {
    declared := make(map[string]TemplateParameter)
    for _, p := range tmpl.Parameters {
        declared[p.Name] = p
    }
    for name := range params {
        if _, ok := declared[name]; !ok {
            return nil, nil, nil, fmt.Errorf("unknown parameter %q", name)
        }
    }
    resolved := make(map[string]interface{})
    defaultsUsed := make([]string, 0)
    for name, p := range declared {
        if val, ok := params[name]; ok {
            if err := validateParamValue(p, val); err != nil {
                return nil, nil, nil, err
            }
            resolved[name] = val
        } else if p.Default != nil {
            resolved[name] = p.Default
            defaultsUsed = append(defaultsUsed, name)
        } else {
            return nil, nil, nil, fmt.Errorf("missing required parameter %q", name)
        }
    }
    sort.Strings(defaultsUsed)
    data, err := json.Marshal(tmpl.Pipeline)
    if err != nil {
        return nil, nil, nil, err
    }
    var p pipeline.Pipeline
    if err := json.Unmarshal(data, &p); err != nil {
        return nil, nil, nil, err
    }
    for _, step := range p.Steps {
        if step.Config != nil {
            for k, v := range step.Config {
                if s, ok := v.(string); ok {
                    if strings.HasPrefix(s, "${param.") && strings.HasSuffix(s, "}") {
                        paramName := s[8 : len(s)-1]
                        val, ok := resolved[paramName]
                        if !ok {
                            return nil, nil, nil, fmt.Errorf("unknown parameter %q", paramName)
                        }
                        step.Config[k] = val
                    }
                }
            }
        }
    }
    return &p, resolved, defaultsUsed, nil
}
```

