package main

import (
        "encoding/json"
        "flag"
        "fmt"
        "log"
        "net/http"
        "os"

        "gomlops/internal/api"
        "gomlops/internal/experiment"
        "gomlops/internal/pipeline"
        "gomlops/internal/registry"
        "gomlops/internal/serving"
)

// Config holds the server configuration.
type Config struct {
        Port    int    `json:"port"`
        DataDir string `json:"data_dir"`
}

func main() {
        configPath := flag.String("config", "/app/configs/config.json", "path to config file")
        flag.Parse()

        cfg, err := loadConfig(*configPath)
        if err != nil {
                log.Fatalf("Failed to load config: %v", err)
        }

        reg, err := registry.NewRegistry(cfg.DataDir + "/registry")
        if err != nil {
                log.Fatalf("Failed to initialize registry: %v", err)
        }

        eng := pipeline.NewEngine()
        tracker := experiment.NewTracker(cfg.DataDir + "/experiments")
        srv := serving.NewServer(reg)

        router := api.NewRouter(reg, eng, tracker, srv)

        addr := fmt.Sprintf(":%d", cfg.Port)
        log.Printf("gomlops server starting on %s", addr)
        log.Printf("data directory: %s", cfg.DataDir)
        if err := http.ListenAndServe(addr, router); err != nil {
                log.Fatalf("Server failed: %v", err)
        }
}

func loadConfig(path string) (*Config, error) {
        data, err := os.ReadFile(path)
        if err != nil {
                return &Config{Port: 8080, DataDir: "/app/data"}, nil
        }
        var cfg Config
        if err := json.Unmarshal(data, &cfg); err != nil {
                return nil, fmt.Errorf("parse config: %w", err)
        }
        if cfg.Port == 0 {
                cfg.Port = 8080
        }
        if cfg.DataDir == "" {
                cfg.DataDir = "/app/data"
        }
        return &cfg, nil
}
